(()=>{
 const storageKey='moodnote-popup-v1';
 const dismissedKey='moodnote-popup-dismissed-v1';
 const today=()=>new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Seoul'}).format(new Date());
 function load(){try{return JSON.parse(localStorage.getItem(storageKey)||'null')}catch{return null}}
 function shouldShow(settings){if(!settings?.enabled)return false;const date=today();if(settings.startDate&&date<settings.startDate)return false;if(settings.endDate&&date>settings.endDate)return false;if(localStorage.getItem(dismissedKey)===date)return false;if(sessionStorage.getItem(dismissedKey)==='1')return false;return true}
 function safeLink(value){const link=String(value||'').trim();return link.startsWith('#')||link.startsWith('/')||/^https:\/\//i.test(link)?link:'#catalog'}
 function close(backdrop){const daily=backdrop.querySelector('[data-popup-daily]').checked;if(daily)localStorage.setItem(dismissedKey,today());else sessionStorage.setItem(dismissedKey,'1');backdrop.remove();document.body.style.removeProperty('overflow')}
 function render(settings){const backdrop=document.createElement('div');backdrop.className=`shop-popup-backdrop ${settings.position==='bottom-right'?'position-bottom-right':''}`;const theme=['cherry','butter','sage'].includes(settings.theme)?settings.theme:'cherry';backdrop.innerHTML=`<section class="shop-popup theme-${theme}" role="dialog" aria-modal="true" aria-labelledby="shop-popup-title"><button class="shop-popup-close-x" type="button" aria-label="팝업 닫기">×</button><div class="shop-popup-art"><span>moodnote</span></div><div class="shop-popup-body"><small>MOODNOTE NOTICE</small><h2 id="shop-popup-title"></h2><p></p><a class="shop-popup-cta"></a></div><div class="shop-popup-footer"><label><input type="checkbox" data-popup-daily> 오늘 하루 보지 않기</label><button type="button" data-popup-close>닫기</button></div></section>`;backdrop.querySelector('h2').textContent=settings.title||'무드노트 소식';backdrop.querySelector('p').textContent=settings.message||'';const cta=backdrop.querySelector('.shop-popup-cta');cta.textContent=settings.buttonLabel||'자세히 보기';cta.href=safeLink(settings.buttonLink);backdrop.addEventListener('click',event=>{if(event.target===backdrop||event.target.closest('[data-popup-close],.shop-popup-close-x'))close(backdrop)});document.body.append(backdrop);document.body.style.overflow='hidden';backdrop.querySelector('.shop-popup-close-x').focus()}
 document.addEventListener('DOMContentLoaded',()=>{const settings=load();if(shouldShow(settings))setTimeout(()=>render(settings),380)});
})();
